 static void state(const Document& d,const JsonObject& expected,bool preview=false){const auto& timeline=preview?d.displayTimeline():d.timeline();const auto* s=timeline.resolveSurface(d.cel().id).surface;check(s&&s->format==timeline::RasterFormat::Indexed&&s->storageOriginX==5&&s->storageOriginY==-3,"surface geometry/origin/format");pixels(s->pixels,expected.GetNamedArray(L"pixels"));palette(preview?d.displayPalette():d.palette(),expected);}
