  auto state=d->timeline_.state();auto l=state.layers.front();l.id="second-layer";state.layers.push_back(l);auto c=state.cels.front();c.id="second-cel";c.layerId=l.id;state.cels.push_back(c);d->timeline_=timeline::Timeline(std::move(state));check(d->beginColorReplacement(targets(*d)),"multi begin");check(d->updateColorReplacement(0xffff0000,0xff0000ff),"multi update");check(d->commitColorAdjustment()&&d->historySize()==1,"multi single history");check(d->timeline_.resolveSurface(c.id).surface->pixels==d->activeSurface().pixels,"multi result");d->undo();check(d->timeline_.resolveSurface(c.id).surface->pixels==d->activeSurface().pixels,"multi undo");d->redo();check(d->timeline_.resolveSurface(c.id).surface->pixels==d->activeSurface().pixels,"multi redo");
